cat > /tmp/dose.py <<'EOF'
import workcell, sys

def net(tare):
    r = workcell.call("scale","read")
    return float(r.data.get("reading_g") if isinstance(r.data,dict) and "reading_g" in r.data else r.text.split()[0]) - tare

def dose_jar(jar, tare, target=250.0):
    workcell.call("robot","pick",jar)
    workcell.call("robot","place","platform")
    # bulk dosing
    while True:
        n = net(tare)
        d = target - n
        if d > 60:
            workcell.call("robot","dose","bulk")
        elif d > 12:
            workcell.call("robot","dose","coarse")
        elif d > 0.6:
            workcell.call("robot","dose","micro")
        else:
            break
    # fine adjust: if over, remove and re-approach
    while True:
        n = net(tare)
        if n < 249.80:
            if n < 248.5: workcell.call("robot","dose","micro")
            else: workcell.call("robot","dose","micro")
        elif n > 250.20:
            workcell.call("robot","remove")
        else:
            break
    r = workcell.call("checkweigher","check")
    print(jar, "check:", r.text)
    workcell.call("robot","pick",jar)
    workcell.call("robot","place","rack")

tares = {"J1":123.22,"J2":119.72,"J3":121.62}
for j in sys.argv[1:]:
    dose_jar(j, tares[j])
EOF
python3 /tmp/dose.py J1

